// Previously this was substring(0, 10000), which kept only the START of the
// meeting. Tasks are usually assigned near the end, so they were cut off.
// Keep the beginning AND most of the end, then let the model-aware fitter
// trim oldest lines if the active model's window is smaller.
const MAX_SUMMARY_CHARS = 40000;
let summaryContext = data.context;
if (summaryContext.length > MAX_SUMMARY_CHARS) {
    const headLen = Math.floor(MAX_SUMMARY_CHARS * 0.2);
    const tailLen = MAX_SUMMARY_CHARS - headLen;
    summaryContext = `${summaryContext.substring(0, headLen)}\n[... middle of meeting omitted ...]\n${summaryContext.substring(summaryContext.length - tailLen)}`;
    console.warn(`[MeetingPersistence] Context ${data.context.length} chars exceeded ${MAX_SUMMARY_CHARS}; kept head+tail.`);
}
summaryContext = this.llmHelper.fitContextForCurrentModel(summaryContext);

const generatedSummary = await this.llmHelper.generateMeetingSummary(summaryPrompt, summaryContext, groqSummaryPrompt);

